SYSCALL_DEFINE3(ioctl, unsigned int, fd, unsigned int, cmd, unsigned long, arg)
{
  struct file *filp;
  int error;
  int fput_needed;

  filp = fget_light(fd, &fput_needed);
  if (!filp)
    return -EBADF;
  error = vfs_ioctl(filp, cmd, arg);
  fput_light(filp, fput_needed);
  return error;
}

