int vfs_ioctl(struct file *filp, unsigned int cmd, unsigned long arg)
{
  return do_vfs_ioctl(filp, cmd, arg);
}

static long do_vfs_ioctl(struct file *filp, unsigned int cmd,
			 unsigned long arg)
{
  int error = 0;
  switch (cmd) {
  case FIOCLEX:
    set_close_on_exec(filp->f_dentry->d_inode->i_fd, 1);
    break;
  case FIONCLEX:
    ...
  case FIONREAD:
    error = put_user(inode->i_size - filp->f_pos,
		     (int __user *)arg);
    break;
  ...
  default:
    if (S_ISREG(inode->i_mode))
      error = file_ioctl(filp, cmd, arg);
    else
      error = vfs_ioctl(filp, cmd, arg);
  }
}

