unsigned long
copy_from_user(void *to, const void __user *from, unsigned long n)
{
  if (likely(access_ok(VERIFY_READ, from, n)))
    n = __copy_from_user(to, from, n);
  return n;
}

unsigned long
copy_to_user(void __user *to, const void *from, unsigned long n)
{
  if (likely(access_ok(VERIFY_WRITE, to, n)))
    n = __copy_to_user(to, from, n);
  return n;
}

#define put_user(x, ptr) ({
  __typeof__(*(ptr)) __pus_tmp = x;
  long __pu_err = -EFAULT;
  might_sleep();
  switch (sizeof(*(ptr))) {
  case 1: __put_user_asm(x, ptr, __pu_err, "b"); break;
  case 2: __put_user_asm(x, ptr, __pu_err, "w"); break;
  case 4: __put_user_asm(x, ptr, __pu_err, "l"); break;
  case 8: __put_user_asm(x, ptr, __pu_err, "q"); break;
  }
  __pu_err;
})

void fput_light(struct file *file, int fput_needed)
{
  if (fput_needed)
    fput(file);
}
